'use strict';
let trained=null,loadError='',latestBatch=[];
const LIVE_KEY='sentineldrift.trained.v1';
const fresh=()=>({schema:2,requests:0,flagged:0,drift:null,champion:'phiusiil-rf-v1',previous:null,candidate:null,canary:false,canarySamples:0,models:[],events:[],predictions:[],runs:[],datasets:[],settings:{threshold:50,canary:10,cooldown:30,enabled:true},history:[]});
try{state=JSON.parse(localStorage.getItem(LIVE_KEY));if(state?.schema!==2)state=fresh()}catch{state=fresh()}
save=function(){try{localStorage.setItem(LIVE_KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Browser storage unavailable. Export your workspace to retain this session.')}};
const legacyBind=bind,legacyAction=action;
const legacySettings=renders.settings;
renders.settings=()=>legacySettings().replaceAll('demo workspace','local workspace').replaceAll('Demo risk threshold','Model score threshold').replaceAll('lexical score','model score').replaceAll('demo workspace','local workspace').replaceAll('Reset demo workspace','Clear local history').replaceAll('Simulated traffic percentage assigned to the candidate (1–50%).','Reserved for future canary serving; does not affect predictions.').replaceAll('Minutes between successful candidate runs (0–1440).','Reserved for future training jobs; no automatic retraining is connected.');
predictionTable=function(){return state.predictions.length?`<div class="table-wrap"><table><thead><tr><th>URL</th><th>MODEL SCORE</th><th>ASSESSMENT</th><th>TIME</th></tr></thead><tbody>${state.predictions.slice(0,30).map(p=>`<tr><td class="mono" style="overflow-wrap:anywhere">${esc(p.url)}</td><td>${p.score.toFixed(1)}/100</td><td>${pill(p.flag?'Likely phishing':'Lower assessed risk',p.flag?'red':'')}</td><td>${new Date(p.time).toLocaleTimeString()}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Analyze your first URL above.</div>'};
window.addEventListener('storage',e=>{if(e.key===LIVE_KEY){try{const next=JSON.parse(e.newValue);if(next?.schema===2){state=next;latestBatch=[];render()}}catch{}}});
function windowRows(){const unique=new Map();for(const p of state.predictions){if(!unique.has(p.url))unique.set(p.url,p);if(unique.size>=200)break}return [...unique.values()]}
function psi(reference,values){const n=reference.counts.length;const current=Array(n).fill(0);for(const value of values){let i=0;while(i<reference.edges.length&&value>=reference.edges[i])i++;current[i]++}const total=reference.counts.reduce((a,b)=>a+b,0);return reference.counts.reduce((s,c,i)=>{const a=(c+.5)/(total+.5*n),b=(current[i]+.5)/(values.length+.5*n);return s+(b-a)*Math.log(b/a)},0)}
function monitor(){const rows=windowRows();if(!trained||rows.length<30)return {ready:false,count:rows.length,features:[],status:'Collecting traffic'};const features=URLModel.names.map((name,j)=>({name,psi:psi(trained.reference[j],rows.map(r=>r.features[j]))}));const high=features.filter(f=>f.psi>.25);const mean=features.reduce((s,f)=>s+f.psi,0)/features.length;return {ready:true,count:rows.length,features,status:high.length?'Distribution shift detected':'No high feature shift',mean,high:high.length}}
function decision(){const m=monitor();if(!state.predictions.length)return {status:'Waiting for a URL',message:'Paste a URL in URL analysis to begin.',action:'Analyze first URL'};if(!m.ready)return {status:'More traffic needed',message:`${m.count}/30 distinct URLs in the monitoring window. The latest URL was scored, but one URL cannot establish population drift.`,action:'Continue collecting traffic'};if(!state.settings.enabled)return {status:'Policy paused',message:'Monitoring continues. New recovery requests are paused in Settings.',action:'Review policy'};if(m.high)return {status:'Awaiting verified labels',message:'Feature distributions differ from training. This does not prove accuracy loss. A candidate cannot be trained or approved from predictions alone.',action:'Collect independently verified labels'};return {status:'No recovery indicated',message:'No high feature shift was detected. Model accuracy still requires verified ground-truth labels.',action:'Continue monitoring'}}
function latestCard(){const p=state.predictions[0];return `<div class="panel-body">${p?`<div class="summary-row"><span>Latest analyzed URL</span>${pill(p.flag?'Likely phishing':'Lower assessed risk',p.flag?'red':'')}</div><p class="mono" style="overflow-wrap:anywhere">${esc(p.url)}</p><div class="summary-row"><span>Model phishing score</span><strong>${p.score.toFixed(1)}/100</strong></div><div class="summary-row"><span>Model version</span><strong>${esc(p.model)}</strong></div><p class="help">${new Date(p.time).toLocaleString()} · Score is not a calibrated probability. Lower assessed risk does not establish safety.</p>`:'<p>No URLs analyzed yet. Start in URL analysis.</p>'}</div>`}
function metricsHTML(){const m=monitor();return `<div class="metrics">${metric('URLs analyzed',state.requests,'Real model inferences in this browser','⌁')}${metric('Flagged predictions',state.flagged,'At the threshold used for each request','◇')}${metric('Distinct URLs in window',m.count,`${Math.max(0,30-m.count)} more needed before drift testing`,'⌇')}${metric('Model state',trained?'Ready':loadError?'Unavailable':'Loading',trained?`${trained.trees.length} trained trees`:'No fallback or fabricated prediction','▧')}</div>`}
scoreURL=function(raw){if(!trained)throw Error(loadError||'Model is loading. Please wait.');const features=URLModel.extract(raw);const p=URLModel.predict(trained,features);return {url:raw,features,score:p*100,flag:p*100>=state.settings.threshold,threshold:state.settings.threshold,model:trained.id,time:new Date().toISOString(),signals:URLModel.names.map((name,i)=>({name,value:features[i],importance:trained.importances[i]})).sort((a,b)=>b.importance-a.importance).slice(0,5).map(x=>`${x.name}: ${x.value.toFixed(3)}`)}};
renders.predictions=function(){return head('TRAINED URL CLASSIFIER','Paste a link. Follow the evidence.','One analysis updates Overview, Drift monitoring, Recovery pipeline, and Audit.')+`<div class="grid">${panel('Analyze a URL',`<div class="panel-body"><form id="live-analysis"><label for="live-urls">HTTP or HTTPS URLs · one per line · maximum 50</label><textarea id="live-urls" required placeholder="Paste the suspicious link here" ${trained?'':'disabled'}></textarea><p class="help">Links are analyzed locally and never opened. This URL-only model cannot inspect page content.</p><br><div class="actions"><button type="submit" class="button primary" ${trained?'':'disabled'}>${trained?'Analyze link':'Model loading…'}</button><button type="button" class="button" data-action="live-samples">Load examples</button></div><p id="live-error" class="error" role="alert">${esc(loadError)}</p></form><div id="live-results" aria-live="polite">${latestBatch.map(p=>`<div class="result">${pill(p.flag?'Likely phishing':'Lower assessed risk',p.flag?'red':'')}<h3>${p.score.toFixed(1)}/100 · model phishing score</h3><p class="mono" style="overflow-wrap:anywhere">${esc(p.url)}</p><p>Model: ${esc(p.model)} · decision threshold ${p.threshold}/100</p><details><summary>Feature measurements</summary><p>${p.signals.map(esc).join('<br>')}</p><p class="help">Listed by global model importance; these are measurements, not local causal explanations.</p></details><br><div class="actions"><a class="button" href="#monitoring">See monitoring →</a><a class="button" href="#recovery">See recovery status →</a></div></div>`).join('')}</div></div>`)}${panel('Latest result shared across panels',latestCard(),trained?pill('TRAINED MODEL'):pill('LOADING','amber'))}</div>`+panel('Prediction history',predictionTable(),btn('Download CSV','prediction-export'))};
renders.overview=function(){const d=decision();return head('LIVE MODEL WORKSPACE','One link. One connected workspace.','Your submitted URLs drive the panels. No generated traffic or simulated recovery.',`<a class="button primary" href="#predictions">Analyze a link →</a>`)+metricsHTML()+`<div class="grid">${panel('Latest model prediction',latestCard())}${panel('Recovery assessment',`<div class="panel-body"><h3>${d.status}</h3><p>${d.message}</p><br><a class="button" href="#recovery">Open recovery status →</a></div>`)}</div>`+panel('Recent activity',`<div class="panel-body">${activity()}</div>`,'<a class="text-button" href="#incidents">View audit →</a>')};
renders.monitoring=function(){const m=monitor();return head('MEASURED FEATURE MONITORING','What changed after your link?','The latest result is immediate. Statistical drift needs at least 30 distinct submitted URLs.',`<a class="button primary" href="#predictions">Analyze another link →</a>`)+metricsHTML()+`<div class="grid">${panel('Latest analyzed link',latestCard())}${panel('Monitoring window',`<div class="panel-body"><h3>${m.status}</h3><p>${m.ready?`${m.high} of ${URLModel.names.length} features exceed PSI 0.25. Mean PSI: ${m.mean.toFixed(3)}. A shift is an alert to investigate, not proof of concept drift.`:`${m.count} distinct URL${m.count===1?'':'s'} collected. Need ${Math.max(0,30-m.count)} more. No drift score is reported before that threshold.`}</p><p class="help">Reference: training-set feature histograms. Current window: latest 200 distinct URLs in retained history. PSI uses smoothed histogram proportions. User-selected traffic may not represent production traffic.</p></div>`)}</div>`+panel('Feature measurements',m.ready?`<div class="table-wrap"><table><thead><tr><th>FEATURE</th><th>MEASURED PSI</th><th>STATUS</th></tr></thead><tbody>${m.features.map(f=>`<tr><td>${f.name}</td><td>${f.psi.toFixed(4)}</td><td>${pill(f.psi>.25?'High shift':f.psi>.1?'Moderate shift':'Low shift',f.psi>.25?'red':'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Insufficient samples. The latest URL is recorded above; population drift is not yet measurable.</div>')};
renders.recovery=function(){const d=decision();return head('EVIDENCE-BASED RECOVERY','What should happen next?','Updated automatically from the same URLs you analyzed.',btn('Refresh assessment','assess',true))+`<div class="grid">${panel('Latest URL driving this assessment',latestCard())}${panel('Current decision',`<div class="panel-body">${pill(d.status,'amber')}<br><br><h3>${d.action}</h3><p>${d.message}</p></div>`)}</div>`+panel('Recovery readiness',`<div class="panel-body"><div class="gate"><span>Trained model available</span>${pill(trained?'Ready':'Loading')}</div><div class="gate"><span>Recent traffic window</span>${pill(monitor().ready?'Ready':`${monitor().count}/30 URLs`,'amber')}</div><div class="gate"><span>Verified production labels</span>${pill('Not connected','amber')}</div><div class="gate"><span>Confirmed performance degradation</span>${pill('Not established','amber')}</div><div class="gate"><span>Retraining / canary deployment</span>${pill('Not enabled','amber')}</div><p class="help">A suspicious prediction is not evidence that this classifier is broken. It does not trigger retraining. No candidate, improvement metric, or deployment is fabricated.</p></div>`)+panel('Assessment history',state.runs.length?`<div class="panel-body">${state.runs.slice(0,15).map(r=>`<div class="activity"><div><h3>${esc(r.status)}</h3><p>${esc(r.detail)}</p><small>${new Date(r.time).toLocaleString()}</small></div></div>`).join('')}</div>`:'<div class="empty">Analyze a URL to record the first recovery assessment.</div>')};
renders.models=function(){return head('MODEL REGISTRY','The actual model behind your prediction.','One trained baseline. No simulated champions or candidate metrics.')+panel('Registered classifier',`<div class="panel-body">${trained?`<h3>${trained.id}</h3><p>${trained.family} · ${trained.trees.length} trees · ${URLModel.names.length} URL-only features</p><div class="summary-row"><span>Training rows</span><strong>${trained.train_rows.toLocaleString()}</strong></div><div class="summary-row"><span>Held-out rows</span><strong>${trained.test_rows.toLocaleString()}</strong></div><div class="summary-row"><span>Held-out phishing F1</span><strong>${trained.metrics.f1.toFixed(4)}</strong></div><div class="summary-row"><span>Held-out false-negative rate</span><strong>${(trained.metrics.fnr*100).toFixed(2)}%</strong></div><div class="summary-row"><span>Held-out false-positive rate</span><strong>${(trained.metrics.fpr*100).toFixed(2)}%</strong></div><p>${esc(trained.split)}</p><p>${esc(trained.limitations)}</p><br><a class="button" href="model-card.json" target="_blank" rel="noopener">Open model card ↗</a><a class="text-button" href="${trained.source_url}" target="_blank" rel="noopener">Dataset attribution ↗</a>`:`<p>${esc(loadError||'Loading model…')}</p>`}</div>`)};
action=function(name){if(name==='live-samples'){$('live-urls').value='https://www.wikipedia.org\nhttp://account-verify.example.xyz/login';return}if(name==='assess'){recordAssessment();render();toast('Assessment refreshed from your current traffic window');return}if(['traffic','attack','recover','fail','canary','observe','promote','rollback'].includes(name)){toast('Simulation controls are disabled in the trained-model workspace.');return}if(name==='export'){download('sentineldrift-live-workspace.json',JSON.stringify({...state,environment:'trained-browser-inference',exportedAt:new Date().toISOString()},null,2));return}if(name==='reset'){showDialog('Clear this local workspace?',`<p>This clears local prediction history and settings. The trained model remains available.</p><button type="button" class="button danger" id="live-reset">Clear local history</button><br><br>`);$('live-reset').onclick=()=>{state=fresh();latestBatch=[];save();$('dialog').close();render()};return}legacyAction(name)};
function recordAssessment(){const d=decision();const p=state.predictions[0];state.runs.unshift({time:new Date().toISOString(),status:d.status,detail:`${p?p.url+' · ':''}${d.message}`});state.runs=state.runs.slice(0,100);save()}
bind=function(){legacyBind();if($('live-analysis'))$('live-analysis').onsubmit=e=>{e.preventDefault();$('live-error').textContent='';try{const urls=$('live-urls').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(!urls.length||urls.length>50)throw Error('Enter 1–50 URLs.');if(urls.some(u=>u.length>4096))throw Error('Maximum URL length is 4096 characters.');latestBatch=urls.map((u,i)=>{try{return scoreURL(u)}catch(err){throw Error(`Line ${i+1}: ${err.message}`)}});state.predictions=[...latestBatch,...state.predictions].slice(0,500);state.requests+=latestBatch.length;state.flagged+=latestBatch.filter(p=>p.flag).length;recordAssessment();event('Trained model prediction',`${latestBatch.length} URLs scored by ${trained.id}; monitoring and recovery updated.`);render()}catch(err){$('live-error').textContent=err.message}}};
document.querySelector('.notice').innerHTML='<span>◈</span><span><strong>Trained model workspace.</strong> URL predictions and feature monitoring use your inputs. Links are never opened. Recovery waits for evidence; automatic retraining is not connected.</span><button id="about-live" class="text-button">Details ↗</button>';
$('about-live').onclick=()=>showDialog('What is live?',`<p>A Random Forest trained on the public UCI PhiUSIIL dataset runs in your browser. Every submitted URL updates analysis, monitoring, recovery assessment and audit. Feature drift needs at least 30 distinct URLs. Confirmed accuracy loss needs independently verified labels. No retraining or deployment is simulated.</p>`);
document.querySelector('.header-right .pill').textContent='● Trained URL model';document.querySelector('.agent').innerHTML='Browser inference<small>Real model · local history</small>';
document.querySelector('footer').innerHTML='<span>SentinelDrift / Trained URL classifier</span><span>Browser-local inference · v0.2</span>';
render();fetch('model.json').then(r=>{if(!r.ok)throw Error(`Model download failed (${r.status})`);return r.json()}).then(m=>{if(!Array.isArray(m.trees)||!m.trees.length||m.reference.length!==URLModel.names.length)throw Error('Invalid model artifact');trained=m;state.champion=state.ops?.champion||m.id;save();render()}).catch(err=>{loadError=err.message;render()});
